const header = document.querySelector('.site-header');
const progressBar = document.querySelector('.progress-bar');
const navLinks = [...document.querySelectorAll('.nav-link')];
const sections = [...document.querySelectorAll('.level')];

function update() {
 const scrollTop = window.scrollY;
 const docHeight = document.documentElement.scrollHeight - window.innerHeight;
 const p = docHeight > 0 ? Math.min(100, Math.max(0, (scrollTop / docHeight) * 100)) : 0;
 progressBar.style.width = p + '%';
 header.classList.toggle('is-scrolled', scrollTop > 8);

 const marker = window.innerHeight * 0.32;
 let activeId = '';
 for (const section of sections) {
   if (section.getBoundingClientRect().top <= marker) activeId = section.id;
 }
 navLinks.forEach(link => link.classList.toggle('active', link.getAttribute('href') === '#' + activeId));
}
let ticking = false;
function onScroll(){ if(!ticking){ requestAnimationFrame(()=>{ update(); ticking=false;}); ticking=true; } }
window.addEventListener('scroll', onScroll, {passive:true});
window.addEventListener('resize', update);
update();

