  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta name="color-scheme" content="dark">
  <title>طبقات الأرض — رحلة إلى مركز الكوكب</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #06111f;
      --bg-deep: #030a13;
      --text: #f2f7fd;
      --soft: #c8d8e8;
      --muted: #97adc3;
      --line: rgba(168, 199, 230, 0.14);
      --line-strong: rgba(168, 199, 230, 0.24);
      --cyan: #7ad8ff;
      --green: #7dd7a8;
      --orange: #d97745;
      --gold: #ffd166;
      --outer-core: #f0a12e;
      --inner-core: #ffe7a0;
      --font: "Noto Sans Arabic", "Noto Kufi Arabic", "Segoe UI", Tahoma, "Geeza Pro", Arial, sans-serif;
      --display: "Noto Kufi Arabic", "Noto Sans Arabic", "Segoe UI", Tahoma, "Geeza Pro", Arial, sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      min-width: 320px;
      margin: 0;
      overflow: hidden;
      color: var(--text);
      background:
        radial-gradient(circle at 78% 10%, rgba(52, 129, 211, 0.2), transparent 36%),
        radial-gradient(circle at 14% 88%, rgba(211, 110, 60, 0.11), transparent 40%),
        linear-gradient(160deg, #071321 0%, var(--bg) 48%, var(--bg-deep) 100%);
      font-family: var(--font);
      line-height: 1.7;
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
    }

    body::before {
      position: fixed;
      inset: 0;
      z-index: 0;
      background-image:
        radial-gradient(circle, rgba(255, 255, 255, 0.5) 0 1px, transparent 1.4px),
        radial-gradient(circle, rgba(140, 213, 255, 0.42) 0 1px, transparent 1.4px);
      background-position: 0 0, 34px 76px;
      background-size: 118px 118px, 184px 162px;
      opacity: 0.12;
      content: "";
      pointer-events: none;
    }

    ::selection {
      color: #071321;
      background: var(--cyan);
    }

    :focus-visible {
      outline: 2px solid var(--cyan);
      outline-offset: 3px;
    }

    button,
    a {
      font: inherit;
    }

    .svg-defs {
      position: absolute;
      width: 0;
      height: 0;
      overflow: hidden;
    }

    .progress-track {
      position: fixed;
      inset: 0 0 auto;
      z-index: 100;
      height: 3px;
      pointer-events: none;
    }

    .progress-bar {
      position: absolute;
      top: 0;
      right: 0;
      width: 0;
      height: 100%;
      background: linear-gradient(90deg, var(--gold), var(--cyan));
      transition: width 400ms cubic-bezier(0.2, 0.8, 0.2, 1);
    }

    .app {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-rows: auto minmax(0, 1fr) auto;
      height: 100dvh;
    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      width: min(1240px, calc(100% - 48px));
      margin: 0 auto;
      padding: 18px 0 12px;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 12px;
      min-width: 0;
    }

    .brand-icon {
      flex: 0 0 auto;
      width: 36px;
      height: 36px;
      filter: drop-shadow(0 6px 18px rgba(122, 216, 255, 0.16));
    }

    .brand strong {
      display: block;
      font-family: var(--display);
      font-size: 1rem;
      font-weight: 800;
      line-height: 1.2;
    }

    .brand span {
      display: block;
      margin-top: 2px;
      color: var(--muted);
      font-size: 0.72rem;
      line-height: 1.35;
    }

    .counter {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 8px 14px;
      color: var(--muted);
      background: rgba(255, 255, 255, 0.025);
      border: 1px solid var(--line);
      border-radius: 999px;
      font-size: 0.78rem;
      font-variant-numeric: tabular-nums;
      white-space: nowrap;
    }

    .counter #currentSlide {
      color: var(--cyan);
      font-size: 1rem;
      font-weight: 800;
    }

    .counter .sep {
      opacity: 0.4;
    }

    .stage {
      overflow-x: hidden;
      overflow-y: auto;
      overscroll-behavior: contain;
      scrollbar-color: rgba(168, 199, 230, 0.25) transparent;
      scrollbar-width: thin;
    }

    .stage::-webkit-scrollbar {
      width: 7px;
    }

    .stage::-webkit-scrollbar-thumb {
      background: rgba(168, 199, 230, 0.22);
      border-radius: 999px;
    }

    .slide {
      display: none;
      min-height: 100%;
    }

    .slide.active {
      display: block;
      animation: slide-in 480ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
    }

    .slide-inner {
      display: grid;
      grid-template-columns: minmax(0, 1.06fr) minmax(0, 0.94fr);
      gap: clamp(30px, 5.5vw, 80px);
      align-items: center;
      width: min(1200px, calc(100% - 48px));
      min-height: 100%;
      margin: 0 auto;
      padding: clamp(24px, 4vh, 48px) 0;
    }

    .copy {
      min-width: 0;
      max-width: 660px;
    }

    .kicker {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      margin: 0 0 18px;
      color: var(--cyan);
      font-size: 0.76rem;
      font-weight: 800;
      line-height: 1.5;
    }

    .kicker::before {
      width: 26px;
      height: 1px;
      background: currentColor;
      opacity: 0.65;
      content: "";
    }

    .display-title {
      margin: 0 0 20px;
      font-family: var(--display);
      font-size: clamp(2.8rem, 5.5vw, 5.6rem);
      font-weight: 800;
      line-height: 1.28;
      text-wrap: balance;
    }

    .display-title .accent {
      display: block;
      color: var(--gold);
    }

    .slide-title {
      margin: 0 0 16px;
      font-family: var(--display);
      font-size: clamp(2rem, 3.8vw, 3.65rem);
      font-weight: 800;
      line-height: 1.35;
      text-wrap: balance;
    }

    .lead {
      max-width: 54ch;
      margin: 0;
      color: var(--soft);
      font-size: clamp(0.98rem, 1.3vw, 1.14rem);
      line-height: 1.95;
    }

    .chips {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      margin-top: 28px;
    }

    .chip {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      padding: 7px 12px;
      color: var(--soft);
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid var(--line);
      border-radius: 999px;
      font-size: 0.78rem;
    }

    .chip i {
      width: 7px;
      height: 7px;
      background: var(--dot);
      border-radius: 50%;
      box-shadow: 0 0 14px var(--dot);
    }

    .hint {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-top: 26px;
      color: var(--muted);
      font-size: 0.78rem;
    }

    .key {
      display: inline-grid;
      place-items: center;
      min-width: 26px;
      height: 26px;
      padding: 0 7px;
      color: var(--soft);
      background: rgba(255, 255, 255, 0.04);
      border: 1px solid var(--line);
      border-radius: 7px;
      font-size: 0.75rem;
      line-height: 1;
    }

    .facts {
      display: grid;
      gap: 10px;
      max-width: 640px;
      margin-top: clamp(20px, 3vh, 30px);
    }

    .fact {
      display: grid;
      grid-template-columns: 9px minmax(0, 1fr);
      gap: 12px;
      padding: 12px 14px;
      background: rgba(255, 255, 255, 0.025);
      border: 1px solid var(--line);
      border-radius: 15px;
    }

    .fact-mark {
      width: 8px;
      height: 8px;
      margin-top: 0.58em;
      background: var(--accent, var(--cyan));
      border-radius: 50%;
      box-shadow: 0 0 14px var(--accent, var(--cyan));
    }

    .fact strong {
      display: block;
      margin-bottom: 2px;
      color: #fff;
      font-size: 0.92rem;
      line-height: 1.55;
    }

    .fact span {
      display: block;
      color: var(--muted);
      font-size: 0.84rem;
      line-height: 1.7;
    }

    .callout {
      max-width: 640px;
      margin-top: 18px;
      padding: 14px 16px;
      color: #f8ecc9;
      background: rgba(255, 209, 102, 0.07);
      border: 1px solid rgba(255, 209, 102, 0.22);
      border-radius: 14px;
      font-size: 0.86rem;
      line-height: 1.8;
    }

    .callout strong {
      color: var(--gold);
    }

    .mini-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 10px;
      max-width: 640px;
      margin-top: 24px;
    }

    .mini-card {
      padding: 16px;
      background: rgba(255, 255, 255, 0.025);
      border: 1px solid var(--line);
      border-radius: 16px;
    }

    .mini-card .tag {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      margin-bottom: 8px;
      color: var(--accent, var(--gold));
      font-size: 0.72rem;
      font-weight: 800;
    }

    .mini-card .tag::before {
      width: 7px;
      height: 7px;
      background: currentColor;
      border-radius: 50%;
      box-shadow: 0 0 12px currentColor;
      content: "";
    }

    .mini-card strong {
      display: block;
      margin-bottom: 4px;
      color: #fff;
      font-size: 0.94rem;
      line-height: 1.5;
    }

    .mini-card p {
      margin: 0;
      color: var(--muted);
      font-size: 0.82rem;
      line-height: 1.75;
    }

    .visual {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 12px;
      min-width: 0;
    }

    .visual-card {
      width: 100%;
      max-width: 550px;
      padding: clamp(10px, 1.7vw, 18px);
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.008));
      border: 1px solid var(--line);
      border-radius: 30px;
      box-shadow: 0 32px 80px rgba(0, 0, 0, 0.2);
    }

    .visual-card svg {
      display: block;
      width: 100%;
      height: auto;
    }

    .earth-svg {
      filter: drop-shadow(0 24px 54px rgba(0, 0, 0, 0.36));
    }

    .diagram-caption {
      max-width: 48ch;
      margin: 0;
      color: var(--muted);
      font-size: 0.77rem;
      line-height: 1.7;
      text-align: center;
    }

    .legend {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 8px 15px;
      color: var(--muted);
      font-size: 0.77rem;
    }

    .legend span {
      display: inline-flex;
      align-items: center;
      gap: 7px;
    }

    .legend i {
      width: 9px;
      height: 9px;
      background: var(--sw);
      border-radius: 50%;
      box-shadow: 0 0 10px var(--sw);
    }

    .svg-label {
      font-family: var(--font);
      font-size: 17px;
      font-weight: 800;
      fill: #f7fbff;
    }

    .svg-label-sm {
      font-family: var(--font);
      font-size: 13px;
      font-weight: 700;
      fill: #f7fbff;
    }

    .svg-tiny {
      font-family: var(--font);
      font-size: 11px;
      font-weight: 800;
      fill: #3e2600;
    }

    .svg-dark {
      fill: #3e2600;
    }

    .svg-line {
      stroke: rgba(201, 225, 247, 0.45);
      stroke-width: 1.4;
    }

    .svg-dash {
      fill: none;
      stroke: rgba(201, 225, 247, 0.3);
      stroke-width: 1.2;
      stroke-dasharray: 4 7;
    }

    .convection {
      fill: none;
      stroke: #ffe5ad;
      stroke-width: 3;
      stroke-linecap: round;
      opacity: 0.78;
    }

    .nav {
      display: grid;
      grid-template-columns: auto 1fr auto;
      align-items: center;
      gap: 16px;
      width: min(1240px, calc(100% - 48px));
      margin: 0 auto;
      padding: 10px 0 20px;
    }

    .nav-btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 9px;
      min-width: 104px;
      padding: 10px 16px;
      color: var(--soft);
      background: rgba(255, 255, 255, 0.035);
      border: 1px solid var(--line);
      border-radius: 999px;
      cursor: pointer;
      font-size: 0.83rem;
      font-weight: 700;
      transition: background 180ms ease, border-color 180ms ease, transform 180ms ease;
    }

    .nav-btn:hover:not(:disabled) {
      background: rgba(255, 255, 255, 0.07);
      border-color: var(--line-strong);
      transform: translateY(-1px);
    }

    .nav-btn.primary {
      color: #fff;
      background: linear-gradient(135deg, rgba(122, 216, 255, 0.18), rgba(255, 209, 102, 0.1));
      border-color: rgba(122, 216, 255, 0.3);
    }

    .nav-btn:disabled {
      opacity: 0.32;
      cursor: not-allowed;
      transform: none;
    }

    .arrow {
      font-size: 1.16rem;
      font-weight: 400;
      line-height: 1;
    }

    .dots {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 9px;
    }

    .dot {
      position: relative;
      width: 8px;
      height: 8px;
      padding: 0;
      background: rgba(196, 217, 238, 0.24);
      border: 0;
      border-radius: 999px;
      cursor: pointer;
      transition: width 250ms ease, background 250ms ease;
    }

    .dot::before {
      position: absolute;
      inset: -8px;
      content: "";
    }

    .dot:hover {
      background: rgba(196, 217, 238, 0.5);
    }

    .dot.active {
      width: 28px;
      background: linear-gradient(90deg, var(--cyan), var(--gold));
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @keyframes slide-in {
      from {
        opacity: 0;
        transform: translateY(14px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    @media (max-width: 980px) {
      .slide-inner {
        grid-template-columns: 1fr;
        gap: 28px;
        padding: 28px 0 38px;
      }

      .copy {
        max-width: 760px;
      }

      .visual {
        order: 2;
      }

      .visual-card {
        max-width: 570px;
      }

      .display-title {
        font-size: clamp(2.6rem, 8vw, 5rem);
      }
    }

    @media (max-width: 640px) {
      .topbar,
      .nav,
      .slide-inner {
        width: calc(100% - 28px);
      }

      .topbar {
        padding-top: 14px;
      }

      .brand-icon {
        width: 30px;
        height: 30px;
      }

      .brand strong {
        font-size: 0.9rem;
      }

      .brand span {
        display: none;
      }

      .counter {
        padding: 6px 10px;
        font-size: 0.7rem;
      }

      .counter #currentSlide {
        font-size: 0.9rem;
      }

      .slide-inner {
        gap: 20px;
        padding: 18px 0 30px;
      }

      .display-title {
        margin-bottom: 16px;
        font-size: clamp(2.15rem, 11vw, 3.3rem);
      }

      .slide-title {
        font-size: clamp(1.75rem, 8vw, 2.5rem);
      }

      .lead {
        font-size: 0.92rem;
        line-height: 1.85;
      }

      .facts {
        margin-top: 18px;
      }

      .fact {
        padding: 10px 12px;
      }

      .fact strong {
        font-size: 0.86rem;
      }

      .fact span,
      .callout,
      .mini-card p {
        font-size: 0.79rem;
      }

      .mini-grid {
        grid-template-columns: 1fr;
      }

      .visual-card {
        border-radius: 22px;
      }

      .nav {
        gap: 8px;
        padding-bottom: 14px;
      }

      .nav-btn {
        min-width: 82px;
        padding: 9px 11px;
        font-size: 0.76rem;
      }

      .dots {
        gap: 6px;
      }

      .dot.active {
        width: 20px;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      html {
        scroll-behavior: auto;
      }

      *,
      *::before,
      *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
    }

    @media print {
      body {
        overflow: visible;
        background: #071321;
      }

      .topbar,
      .nav,
      .progress-track {
        display: none;
      }

      .app {
        display: block;
        height: auto;
      }

      .stage {
        overflow: visible;
      }

      .slide {
        display: block !important;
        break-after: page;
        page-break-after: always;
      }

      .slide-inner {
        min-height: auto;
      }
    }
  </style>
</head>
<body>
  <svg class="svg-defs" aria-hidden="true" focusable="false" width="0" height="0">
    <defs>
      <radialGradient id="gCrust" cx="30%" cy="25%" r="85%">
        <stop offset="0%" stop-color="#b7f0cf"/>
        <stop offset="60%" stop-color="#66b98d"/>
        <stop offset="100%" stop-color="#2f7c5d"/>
      </radialGradient>
      <radialGradient id="gMantle" cx="38%" cy="30%" r="80%">
        <stop offset="0%" stop-color="#f0a060"/>
        <stop offset="48%" stop-color="#ca6535"/>
        <stop offset="100%" stop-color="#74301d"/>
      </radialGradient>
      <radialGradient id="gOuter" cx="38%" cy="32%" r="75%">
        <stop offset="0%" stop-color="#ffd76a"/>
        <stop offset="55%" stop-color="#eea02a"/>
        <stop offset="100%" stop-color="#b86513"/>
      </radialGradient>
      <radialGradient id="gInner" cx="35%" cy="30%" r="80%">
        <stop offset="0%" stop-color="#fffbe0"/>
        <stop offset="65%" stop-color="#ffe28a"/>
        <stop offset="100%" stop-color="#eab63f"/>
      </radialGradient>
      <radialGradient id="gShine" cx="34%" cy="26%" r="72%">
        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.24"/>
        <stop offset="42%" stop-color="#ffffff" stop-opacity="0.02"/>
        <stop offset="100%" stop-color="#000000" stop-opacity="0.48"/>
      </radialGradient>
      <linearGradient id="gMantleBand" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="#df8248"/>
        <stop offset="100%" stop-color="#8f3a22"/>
      </linearGradient>
      <linearGradient id="gLand" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="#7e9b78"/>
        <stop offset="100%" stop-color="#536c55"/>
      </linearGradient>
      <linearGradient id="gOcean" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="#1d6a99"/>
        <stop offset="100%" stop-color="#0d3d60"/>
      </linearGradient>
    </defs>
  </svg>

  <div class="progress-track" aria-hidden="true">
    <div class="progress-bar" id="progressBar"></div>
  </div>

  <div class="app">
    <header class="topbar">
      <div class="brand">
        <svg class="brand-icon" viewBox="0 0 40 40" aria-hidden="true">
          <circle cx="20" cy="20" r="18" fill="#0a1c2f" stroke="rgba(255,255,255,.22)" stroke-width="1"/>
          <circle cx="20" cy="20" r="15" fill="url(#gCrust)"/>
          <circle cx="20" cy="20" r="12" fill="url(#gMantle)"/>
          <circle cx="20" cy="20" r="5.6" fill="url(#gOuter)"/>
          <circle cx="20" cy="20" r="2.2" fill="url(#gInner)"/>
          <circle cx="20" cy="20" r="18" fill="url(#gShine)"/>
        </svg>
        <div>
          <strong>طبقات الأرض</strong>
          <span>رحلة من السطح إلى المركز</span>
        </div>
      </div>

      <div class="counter" aria-live="polite" aria-atomic="true">
        <span id="currentSlide">1</span>
        <span class="sep">/</span>
        <span>6</span>
      </div>
    </header>

    <main class="stage" id="stage">
      <section class="slide active" data-title="رحلة إلى مركز الأرض" aria-labelledby="title-1">
        <div class="slide-inner">
          <div class="copy">
            <p class="kicker">عرض مرئي تفاعلي</p>
            <h1 class="display-title" id="title-1">
              رحلة إلى
              <span class="accent">مركز الأرض</span>
            </h1>
            <p class="lead">
              ماذا يوجد تحت أقدامنا؟ ثلاثة عوالم متراكبة تشكّل كوكبنا: قشرة رقيقة نعيش عليها، ووشاح هائل يتحرك ببطء، ولب معدني متوهج في القلب.
            </p>
            <div class="chips" aria-label="طبقات الأرض الرئيسية">
              <span class="chip"><i style="--dot: var(--green)"></i>القشرة</span>
              <span class="chip"><i style="--dot: var(--orange)"></i>الوشاح</span>
              <span class="chip"><i style="--dot: var(--gold)"></i>اللب</span>
            </div>
            <div class="hint">
              <span class="key">←</span>
              <span class="key">→</span>
              تنقّل بين الشرائح باستخدام الأسهم أو الأزرار أدناه
            </div>
          </div>

          <div class="visual">
