{"content": "#!/usr/bin/env python3
"""Analyze returns by primary book genre."""

import csv
from collections import defaultdict
from decimal import Decimal, ROUND_HALF_UP

INPUT_FILE = "bookstore_orders.csv"
OUTPUT_FILE = "genre-returns.csv"
CENTS = Decimal("0.01")
HUNDRED = Decimal("100")


def main() -> None:
    genres = defaultdict(
        lambda: {
            "total_orders": 0,
            "returned_orders": 0,
            "total_refund": Decimal("0"),
        }
    )

    with open(INPUT_FILE, newline="", encoding="utf-8") as infile:
        for row in csv.DictReader(infile):
            genre = row["primary_item_genre"].strip()
            stats = genres[genre]

            stats["total_orders"] += 1
            if row["return_requested"].strip().lower() == "yes":
                stats["returned_orders"] += 1

            stats["total_refund"] += Decimal(row["refund_amount"] or "0")

    results = []
    for genre, stats in genres.items():
        return_rate = (
            Decimal(stats["returned_orders"]) / Decimal(stats["total_orders"]) * HUNDRED
        ).quantize(CENTS, rounding=ROUND_HALF_UP)
        total_refund = stats["total_refund"].quantize(CENTS, rounding=ROUND_HALF_UP)

        results.append(
            {
                "genre": genre,
                "total_orders": stats["total_orders"],
                "returned_orders": stats["returned_orders"],
                "return_rate": return_rate,
                "total_refund": total_refund,
            }
        )

    results.sort(
        key=lambda item: (-item["return_rate"], -item["total_refund"], item["genre"])
    )

    with open(OUTPUT_FILE, "w", newline="", encoding="utf-8") as outfile:
        writer = csv.writer(outfile)
        writer.writerow(
            ["Genre", "TotalOrders", "ReturnedOrders", "ReturnRatePct", "TotalRefund"]
        )
        for item in results:
            writer.writerow(
                [
                    item["genre"],
                    item["total_orders"],
                    item["returned_orders"],
                    f"{item['return_rate']:.2f}",
                    f"{item['total_refund']:.2f}",
                ]
            )


