fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "--"

    val seconds = exposureTimeNs / 1_000_000_000.0

    if (seconds >= 0.5) {
        return String.format(java.util.Locale.US, "%.2f", seconds)
            .trimEnd('0')
            .trimEnd('.') + "s"
    }

    val denominator = (1.0 / seconds).roundToInt()
    if (denominator > 0) {
        val represented = 1.0 / denominator
        if (Math.abs(represented - seconds) <= seconds * 0.05) {
            return "1/${denominator}s"
        }
    }

    return String.format(java.util.Locale.US, "%.3f", seconds)
        .trimEnd('0')
        .trimEnd('.') + "s"
}

