fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "--"

    val seconds = exposureTimeNs / NANOS_PER_SECOND
    val denominator = (1.0 / seconds).roundToInt()
    val reciprocalAccurate = denominator > 0 && abs(1.0 / denominator - seconds) <= seconds * 0.05

    if (seconds < 0.5 && reciprocalAccurate) {
        return "1/${denominator}s"
    }
    return formatSeconds(seconds)
}

private fun formatSeconds(seconds: Double): String {
    val pattern = if (seconds < 0.5) "%.3f" else "%.2f"
    return String.format(Locale.US, pattern, seconds)
        .trimEnd('0')
        .trimEnd('.') + "s"
}

